WITH catalog AS (SELECT cs.cs_item_sk AS item_sk, cs.cs_net_profit AS net_profit, cs.cs_sales_price AS sales_price, cs.cs_bill_customer_sk AS cust_sk, ca.ca_state AS state FROM catalog_sales cs JOIN customer c ON cs.cs_bill_customer_sk = c.c_customer_sk JOIN customer_address ca ON cs.cs_bill_addr_sk = ca.ca_address_sk), store AS (SELECT ss.ss_item_sk AS item_sk, ss.ss_net_profit AS net_profit, ss.ss_sales_price AS sales_price, ss.ss_customer_sk AS cust_sk, ca.ca_state AS state FROM store_sales ss JOIN customer c ON ss.ss_customer_sk = c.c_customer_sk JOIN customer_address ca ON ss.ss_addr_sk = ca.ca_address_sk), web AS (SELECT ws.ws_item_sk AS item_sk, ws.ws_net_profit AS net_profit, ws.ws_sales_price AS sales_price, ws.ws_bill_customer_sk AS cust_sk, ca.ca_state AS state FROM web_sales ws JOIN customer c ON ws.ws_bill_customer_sk = c.c_customer_sk JOIN customer_address ca ON ws.ws_bill_addr_sk = ca.ca_address_sk), combined AS (SELECT * FROM catalog UNION ALL SELECT * FROM store UNION ALL SELECT * FROM web), state_agg AS (SELECT state, SUM(net_profit) AS state_net_profit FROM combined GROUP BY state HAVING SUM(net_profit) > 1000000), item_agg AS (SELECT c.item_sk, c.state, SUM(c.net_profit) AS total_net_profit, SUM(c.sales_price) AS total_sales_price, COUNT(DISTINCT c.cust_sk) AS distinct_customers FROM combined c JOIN state_agg s ON c.state = s.state GROUP BY c.item_sk, c.state) SELECT item_sk, state, total_net_profit, total_sales_price, distinct_customers, RANK() OVER (ORDER BY total_net_profit DESC) AS profit_rank FROM item_agg ORDER BY total_net_profit DESC LIMIT 10
